import { Component } from '@angular/core';

interface Operacion {
  numero1: number;
  numero2: number;
  operador: string;
  resultado: number;
}

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  numero1: number | null = null;
  numero2: number | null = null;
  operador: string = '+';

  resultado: number | null = null;

  historial: Operacion[] = [];

  calcular(): void {
    if (this.numero1 === null || this.numero2 === null) {
      return;
    }

    let resultado = 0;

    switch (this.operador) {
      case '+':
        resultado = this.numero1 + this.numero2;
        break;
      case '-':
        resultado = this.numero1 - this.numero2;
        break;
      case '*':
        resultado = this.numero1 * this.numero2;
        break;
      case '/':
        if (this.numero2 === 0) {
          alert('No se puede dividir entre 0');
          return;
        }
        resultado = this.numero1 / this.numero2;
        break;
    }

    this.resultado = resultado;

    this.historial.unshift({
      numero1: this.numero1,
      numero2: this.numero2,
      operador: this.operador,
      resultado: resultado
    });
  }

  limpiarHistorial(): void {
    this.historial = [];
  }

  simboloOperador(operador: string): string {
    switch (operador) {
      case '+': return '+';
      case '-': return '-';
      case '*': return '×';
      case '/': return '÷';
      default: return operador;
    }
  }
}
<div class="contenedor">
  <h1>Calculadora</h1>

  <div class="formulario">
    <label>
      Número 1
      <input type="number" [(ngModel)]="numero1" placeholder="">
    </label>

    <label>
      Número 2
      <input type="number" [(ngModel)]="numero2" placeholder="">
    </label>

    <label>
      Operación
      <select [(ngModel)]="operador">
        <option value="+">(+)</option>
        <option value="-">(-)</option>
        <option value="*">(×)</option>
        <option value="/">(÷)</option>
      </select>
    </label>

    <button (click)="calcular()">Calcular</button>

    <label>
      Resultado
      <input type="text" [value]="resultado" disabled placeholder="">
    </label>
  </div>

  <div class="historial">
    <div class="historial-titulo">
      <h2>Historial</h2>
    </div>

    <p *ngIf="historial.length === 0"></p>

    <ul *ngIf="historial.length > 0">
      <li *ngFor="let op of historial">
        {{ op.numero1 }} {{ simboloOperador(op.operador) }} {{ op.numero2 }} = {{ op.resultado }}
      </li>
    </ul>
  </div>
</div>
